mapper.select:
SELECT * FROM ai_task WHERE tenant_id=#{tenant} AND owner_id=#{owner} AND kind=#{kind}

  AND (created_at < #{before} OR (created_at=#{before} AND task_id < #{cursor}))

ORDER BY created_at DESC,task_id DESC LIMIT #{limit}

SELECT * FROM ai_task WHERE tenant_id=#{tenant} AND runtime_version=#{runtime} AND graph_version=#{graph}
  AND (status='QUEUED' OR (status='RUNNING' AND lease_expires_at<=UTC_TIMESTAMP(6)))
ORDER BY created_at,task_id LIMIT 1 FOR UPDATE SKIP LOCKED

mapper.update:
UPDATE ai_task SET lease_expires_at=TIMESTAMPADD(SECOND,#{seconds},UTC_TIMESTAMP(6))
WHERE task_id=#{id} AND status='RUNNING' AND worker_id=#{worker}
    AND lease_epoch=#{epoch} AND lease_expires_at>UTC_TIMESTAMP(6)
